-- Courier bookings (docs/plans/cart-checkout.md §3 "Phase K migrations", §15 Phase K, K2): the
-- shipments table (one row per booking attempt; a partial UNIQUE keeps at most one live attempt per
-- order, so a booking is never made twice) and two new needs_attention flags,
-- shipping_cost_over_quote (decision 47) and tracking_number_mismatch (owner 2026-10-22: staff typed
-- a resi other than the booked waybill).
-- Generated by drizzle-kit, then read. Hand edits: this header and the lock_timeout line.
--
-- Backward compatibility with the previous release (K1; CLAUDE.md expand/contract): additive. A new
-- table nothing released reads or writes, and a CHECK on orders.needs_attention replaced by a strict
-- superset (every row valid before is valid after, and the K1 image never writes the new values).
-- Rollback reading a new flag: apps/web never reads needs_attention and the admin order list only
-- counts flags; the K1 admin's order page has no copy for the two new flags and shows its error
-- page for an order carrying one (dev only: prod's image predates needs_attention; owner decision
-- 2026-10-22). From K2 on the admin renders any unknown flag safely.
--
-- Locks: re-adding the orders CHECK takes ACCESS EXCLUSIVE on orders and scans it (a few thousand
-- rows, well under a second); the foreign keys take brief SHARE ROW EXCLUSIVE locks on orders and
-- staff_users and validate against an empty table. lock_timeout makes the migration fail fast (and
-- roll back entirely) instead of queueing every order read behind a long-running transaction.
SET LOCAL lock_timeout = '5s';--> statement-breakpoint
CREATE TABLE "shipments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"attempt" integer NOT NULL,
	"reference_id" text NOT NULL,
	"provider" text NOT NULL,
	"provider_order_id" text,
	"provider_tracking_id" text,
	"courier" text NOT NULL,
	"service" text NOT NULL,
	"awb" text,
	"routing_code" text,
	"tracking_link" text,
	"cost_amount" bigint,
	"status" text DEFAULT 'booking' NOT NULL,
	"provider_status" text,
	"last_error" text,
	"driver_name" text,
	"driver_phone" text,
	"driver_plate_number" text,
	"booked_at" timestamp with time zone,
	"picked_up_at" timestamp with time zone,
	"delivered_at" timestamp with time zone,
	"cancel_requested_at" timestamp with time zone,
	"cancelled_at" timestamp with time zone,
	"failed_at" timestamp with time zone,
	"last_polled_at" timestamp with time zone,
	"last_event_at" timestamp with time zone,
	"booked_by_staff_user_id" uuid,
	"cancelled_by_staff_user_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "shipments_reference_id_key" UNIQUE("reference_id"),
	CONSTRAINT "shipments_provider_order_id_key" UNIQUE("provider_order_id"),
	CONSTRAINT "shipments_order_id_attempt_key" UNIQUE("order_id","attempt"),
	CONSTRAINT "shipments_provider_check" CHECK ("shipments"."provider" in ('biteship')),
	CONSTRAINT "shipments_status_check" CHECK ("shipments"."status" in ('booking', 'failed', 'pickup_requested', 'picked_up', 'in_transit', 'delivered', 'cancelled', 'returning', 'returned', 'problem')),
	CONSTRAINT "shipments_attempt_check" CHECK ("shipments"."attempt" between 1 and 99),
	CONSTRAINT "shipments_cost_amount_check" CHECK ("shipments"."cost_amount" is null or "shipments"."cost_amount" >= 0),
	CONSTRAINT "shipments_provider_order_id_check" CHECK ("shipments"."status" in ('booking', 'failed') or "shipments"."provider_order_id" is not null),
	CONSTRAINT "shipments_failed_consistency_check" CHECK (("shipments"."status" = 'failed') = ("shipments"."failed_at" is not null)),
	CONSTRAINT "shipments_failed_unbooked_check" CHECK ("shipments"."status" <> 'failed' or "shipments"."provider_order_id" is null),
	CONSTRAINT "shipments_cancelled_at_check" CHECK ("shipments"."status" <> 'cancelled' or "shipments"."cancelled_at" is not null)
);
--> statement-breakpoint
ALTER TABLE "orders" DROP CONSTRAINT "orders_needs_attention_allowed_check";--> statement-breakpoint
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_booked_by_staff_user_id_staff_users_id_fk" FOREIGN KEY ("booked_by_staff_user_id") REFERENCES "public"."staff_users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_cancelled_by_staff_user_id_staff_users_id_fk" FOREIGN KEY ("cancelled_by_staff_user_id") REFERENCES "public"."staff_users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "shipments_live_order_id_key" ON "shipments" USING btree ("order_id") WHERE "shipments"."status" not in ('cancelled', 'failed');--> statement-breakpoint
CREATE INDEX "shipments_open_last_polled_at_idx" ON "shipments" USING btree ("last_polled_at") WHERE "shipments"."status" not in ('cancelled', 'failed', 'delivered', 'returned');--> statement-breakpoint
CREATE INDEX "shipments_booked_by_staff_user_id_idx" ON "shipments" USING btree ("booked_by_staff_user_id");--> statement-breakpoint
CREATE INDEX "shipments_cancelled_by_staff_user_id_idx" ON "shipments" USING btree ("cancelled_by_staff_user_id");--> statement-breakpoint
